+
+export function summarizeRuns(records) {
+  if (!Array.isArray(records)) throw new TypeError("records must be an array");
+
+  const durations = records
+    .filter(record => record !== null && typeof record === "object" && record.status === "ok")
+    .map(record => {
+      const { durationMs } = record;
+      if (typeof durationMs !== "number" || !Number.isFinite(durationMs) || durationMs < 0) {
+        throw new TypeError("successful runs require a finite nonnegative durationMs");
+      }
+      return durationMs;
+    });
+
+  const count = durations.length;
+  const totalMs = sumNumbers(durations);
+  return { count, totalMs, meanMs: count === 0 ? 0 : totalMs / count };
+}
