+import test from "node:test";
+import assert from "node:assert/strict";
+import { summarizeRuns } from "../metrics.mjs";
+
+test("summarizeRuns summarizes only successful runs", () => {
+  const records = [
+    { status: "ok", durationMs: 10 },
+    { status: "failed", durationMs: 500 },
+    { status: "ok", durationMs: 30 },
+    { status: "skipped", durationMs: 1 },
+    { status: "ok", durationMs: 0 },
+  ];
+
+  assert.deepEqual(summarizeRuns(records), {
+    count: 3,
+    totalMs: 40,
+    meanMs: 40 / 3,
+  });
+});
+
+test("summarizeRuns returns all zeros for an empty or fully unsuccessful set", () => {
+  const empty = { count: 0, totalMs: 0, meanMs: 0 };
+  assert.deepEqual(summarizeRuns([]), empty);
+  assert.deepEqual(
+    summarizeRuns([
+      { status: "failed", durationMs: 12 },
+      { status: "ignored" },
+    ]),
+    empty,
+  );
+});
+
+test("summarizeRuns rejects a non-array argument", () => {
+  for (const value of [undefined, null, "records", 42, {}, { length: 0 }]) {
+    assert.throws(() => summarizeRuns(value), TypeError);
+  }
+});
+
+test("summarizeRuns rejects malformed successful records", () => {
+  const invalidDurations = [undefined, null, NaN, Infinity, -Infinity, -1, "5", true, {}];
+  for (const durationMs of invalidDurations) {
+    assert.throws(
+      () => summarizeRuns([{ status: "ok", durationMs }]),
+      TypeError,
+      `expected durationMs=${String(durationMs)} to be rejected`,
+    );
+  }
+
+  assert.throws(() => summarizeRuns([{ status: "ok" }]), TypeError);
+  assert.throws(
+    () => summarizeRuns([{ status: "ok", durationMs: 10 }, { status: "ok", durationMs: Infinity }]),
+    TypeError,
+  );
+});
+
+test("summarizeRuns ignores malformed durations on unsuccessful records", () => {
+  assert.deepEqual(
+    summarizeRuns([
+      { status: "failed", durationMs: NaN },
+      { status: "failed", durationMs: -3 },
+      { status: "failed" },
+      { status: "ok", durationMs: 7 },
+    ]),
+    { count: 1, totalMs: 7, meanMs: 7 },
+  );
+
+  assert.deepEqual(
+    summarizeRuns([null, 42, "ok", {}, { status: "ok", durationMs: 4 }]),
+    { count: 1, totalMs: 4, meanMs: 4 },
+  );
+});
+
+test("summarizeRuns computes fractional means without losing the total", () => {
+  assert.deepEqual(
+    summarizeRuns([
+      { status: "ok", durationMs: 1 },
+      { status: "ok", durationMs: 2 },
+    ]),
+    { count: 2, totalMs: 3, meanMs: 1.5 },
+  );
+});
